html:
{% from "hipersign_trading/templates/print/macros.html" import styles, header, items, totals, signs, bank %}
{{ styles() }}
<div class="hs-doc">
{{ header("PURCHASE ORDER", "أمر شراء", doc.name, doc.transaction_date, doc.company) }}
<div class="hs-two"><div><div class="hs-h4">Supplier · المورد</div><b>{{ doc.supplier_name }}</b><br>{{ doc.address_display or "" }}{% if doc.contact_display %}<br>Attn: {{ doc.contact_display }}{% if doc.contact_mobile %} · {{ doc.contact_mobile }}{% endif %}{% endif %}{% if doc.tax_id %}<br>TRN {{ doc.tax_id }}{% endif %}</div><div><div class="hs-h4">Terms · الشروط</div>Incoterm: {{ doc.incoterm or "—" }} {{ doc.named_place or "" }}<br>Currency: {{ doc.currency }}<br>Required by: {{ frappe.utils.formatdate(doc.schedule_date) }}<br>Deliver to: {{ doc.set_warehouse or "Main Warehouse" }}</div></div>
{{ items(doc, show_hs=True, show_disc=False) }}
{{ totals(doc) }}
<div class="hs-note">Please confirm acceptance and send the proforma invoice, packing list and expected shipping date. Original commercial invoice, packing list, certificate of origin and bill of lading / AWB are required for customs clearance.</div>
{{ signs("Authorised signatory — " ~ doc.company, "Supplier acceptance") }}
</div>
